css:
.switch__input {
  color: hsl(223, 10%, 90%);
  font-size: 15px;
}
.switch,
.switch__input,
.switch__handle-sides,
.switch__handle-side,
.switch__handle-labels,
.switch__handle-label,
.switch__handle-texture {
  display: block;
}
.switch,
.switch__input {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.switch {
  margin: auto;
  position: relative;
  width: 5em;
  height: 5em;
}
.switch__input {
  border-radius: 0.25em;
  outline: transparent;
  position: relative;
  width: 100%;
  height: 100%;
  transition:
    background-color 0.4s,
    box-shadow 0.4s;
  -webkit-appearance: none;
  appearance: none;
}
.switch__input:before {
  border-radius: inherit;
  box-shadow: 0 0 0 max(0.125em, 1px) hsla(223, 90%, 50%, 0);
  content: "";
  display: block;
  position: absolute;
  inset: 0;
  transition: box-shadow 0.15s linear;
}
.switch__input:focus-visible:before {
  box-shadow: 0 0 0 max(0.125em, 1px) hsla(223, 90%, 50%, 1);
}
.switch__handle,
.switch__handle-sides,
.switch__handle-side,
.switch__handle-labels,
.switch__handle-label {
  position: absolute;
}
.switch__handle,
.switch__handle-label {
  transition: transform 0.4s cubic-bezier(0.65, 0, 0.36, 1.6);
}
.switch__handle,
.switch__handle-sides,
.switch__handle-texture {
  border-radius: 0.125em;
}
.switch__handle {
  box-shadow: 0.25em 0.25em 0.25em hsla(223, 10%, 10%, 0.4);
  top: 31%;
  left: 30%;
  width: 40%;
  height: 80%;
  rotate: 270deg;
}
.switch__handle-sides,
.switch__handle-labels,
.switch__handle-texture {
  width: 100%;
  height: 100%;
}
.switch__handle-sides,
.switch__handle-side {
  background-color: hsl(223, 10%, 85%);
  transition:
    background-color 0.4s,
    transform 0.4s cubic-bezier(0.65, 0, 0.36, 1.6);
}
.switch__handle-sides {
  --side-on: hsl(123, 90%, 40%);
  background-image: linear-gradient(90deg, transparent 50%, var(--side-on) 50%);
  overflow: hidden;
}
.switch__handle-side {
  background-image: linear-gradient(90deg, var(--side-on) 50%, transparent 50%);
  transform: translateX(-50%);
  width: 200%;
  height: 100%;
}
.switch__handle-labels {
  transform-style: preserve-3d;
  -webkit-user-select: none;
  -moz-user-select: none;
  user-select: none;
}
.switch__handle-label {
  backface-visibility: hidden;
  font-size: 15px;
  text-shadow: 0 0 0.125em hsla(223, 10%, 10%, 0.3);
  line-height: 1;
  top: 50%;
  left: 50%;
  text-align: center;
  text-transform: uppercase;
  transform: translate(-50%, -50%) rotateZ(90deg) rotateX(0) translateZ(0.55rem);
}
.switch__handle-label + .switch__handle-label {
  color: hsl(0, 0%, 100%);
  text-shadow: 0 0 0.125em hsla(0, 0%, 100%, 0.3);
  transform: translate(-50%, -50%) rotateZ(90deg) rotateX(180deg)
    translateZ(0.55rem);
}
.switch__handle-texture {
  background-image: linear-gradient(
    90deg,
    hsla(0, 0%, 100%, 0),
    hsla(0, 0%, 100%, 0.3) 20%,
    hsla(0, 0%, 100%, 0) 40%,
    hsla(0, 0%, 0%, 0) 50%,
    hsla(0, 0%, 0%, 0.4)
  );

  transform: translateZ(0);
}
.switch__input:checked ~ .switch__handle {
  transform: translateX(100%);
}
.switch__input:checked ~ .switch__handle .switch__handle-side {
  transform: translateX(0);
}
.switch__input:checked ~ .switch__handle .switch__handle-label {
  transform: translate(-50%, -50%) rotateZ(90deg) rotateX(180deg)
    translateZ(0.55rem);
}
.switch__input:checked
  ~ .switch__handle
  .switch__handle-label
  + .switch__handle-label {
  transform: translate(-50%, -50%) rotateZ(90deg) rotateX(360deg)
    translateZ(0.55rem);
}
.switch__label {
  overflow: hidden;
  position: absolute;
  width: 1px;
  height: 1px;
}

/* Dark theme */
@media (prefers-color-scheme: dark) {
  :root {
    --bg: hsl(223, 10%, 30%);
    --fg: hsl(223, 10%, 90%);
  }
  .switch__handle-sides,
  .switch__handle-side {
    background-color: hsl(0, 100%, 70%);
  }
  .switch__handle-label {
    text-shadow: 0 0 0.125em hsla(223, 10%, 90%, 0.3);
  }
  .switch__input {
    background-color: hsl(223, 10%, 35%);
    box-shadow:
      0.125em 0.125em 0.125em hsl(240, 1%, 30%) inset,
      -0.125em -0.125em 0.125em hsl(220, 2%, 39%) inset,
      0.125em 0.125em 0.375em hsl(0, 0%, 82%);
  }
}
